"""Solar System Colonization's 40 worlds, from one table.

Every per-world block of the colony record is written from ``SITES`` below.
Design: ``docs/superpowers/specs/2026-10-25-solar-colonization-holders-and-cession-design.md``
(slices 0-1), ``...-population-and-transit-design.md`` (slices 2-3),
``...-modules-and-bases-design.md`` (slice 4) and
``2026-10-26-solar-colonization-free-colonies-design.md`` (slice 5: autonomy,
free colonies, abandonment, the covert hooks, colony life). The Moon's six
worlds, stage 0, are ``2026-10-29-lunar-colonization-design.md`` § 3.

The global record is the truth: ``sr_site_holder_<key>`` (the holder, a
country), ``sr_site_spec_<key>`` (1 or 2, the specialization chosen in the
founding event), ``sr_site_region_<key>`` (the holder's capital state region),
``sr_site_mirror_<key>`` (the country whose variables show the site), and per
discovery ``sr_site_disc_<d>`` (1 or 2) and ``sr_site_disc_<d>_pending``. The
holder's ``<modifier>_held`` variables are the projection, written by
``sr_site_sync_<key>``; its journal entry declares each modifier while the
variable is held (1.15 ``scaling_modifiers_while_active``, #1404). Slice 5 adds ``sr_site_free_<key>``
(a free colony: claimed, no holder), ``sr_site_autonomy_<key>`` and the rest of
``slice5_vars()``, all cleared by a release.

Outputs:

- ``common/scripted_effects/sr_sites_generated.txt``: the founding draw and the
  stage check (``sr_launch_month`` calls the draw), and per world the sync,
  mirror, release, transfer and monthly step; the choice dispatcher
  (``sr_site_choose_<modifier>``, an option of the founding and discovery
  events); the revolution repoint, the panel snapshot, Cede
  Colony's apply and the console's helpers; each room building's next-day hook
  (``ROOM_BUILDINGS``, below).
- ``common/journal_entries/sr_sites_generated.txt``: the solar colonization
  entry's declarations of the 80 specializations, the 40 discovery outcomes
  (under races only; under simple and full colonies an outcome is its world's
  boon, ``DISCOVERY_BOONS``) and the six facilities (an ``INJECT:`` into the
  hand-written entry, ``je_space_race.txt``).
- ``common/scripted_triggers/sr_sites_generated.txt``: Cede Colony's input filter
  and ``sr_any_site_unclaimed``; each room building's build gates.
- ``common/script_values/sr_sites_generated.txt``: ``sr_sites_held_count`` and the
  AI's value of a ceded world; each room building's levels and room.
- ``common/script_values/sr_sites_display_generated.txt``: the panel's
  ``sr_disp_site_<key>`` and each room building's overview cell, read by the GUI
  only.
- ``common/buildings/sr_site_buildings_generated.txt``: one hidden building type
  per world, which only names it in the treaty designer.
- ``common/customizable_localization/sr_sites_generated_custom_loc.txt``: a
  world's name from its index, for the notices.

The room buildings (``ROOM_BUILDINGS``, #1951) are the Extraplanetary Base and the
Resort Colony, whose levels fill a room their country's colonies give them: the
pieces of that room still the same shape for both are written by one function
each (``render_room_*``, ``site_room_*``), called once a building.

The table is the script's own: each world's stage, launch-window body
(``gen_launch_windows.BODIES``; Mercury and the Moon have none), founding event
(``space_race_colony_events.N``), the two specializations its event offers in
option order, and the discoveries its founding seeds. ``test_solar_sites.py``
re-derives all of them from the events and the launch windows and fails when the
table and the script disagree.

Run ``python3 scripts/generators/gen_solar_sites.py [--dry-run | --check]``.
A post-load regenerator (``mod_state_server.POST_LOAD_REGENERATORS``).
"""

from __future__ import annotations

import argparse
import re
import sys
