ENTRY_OUT = Path("common/journal_entries/sr_sites_generated.txt")
DISPLAY_OUT = Path("common/script_values/sr_sites_display_generated.txt")
BUILDINGS_OUT = Path("common/buildings/sr_site_buildings_generated.txt")
CUSTOM_LOC_OUT = Path("common/customizable_localization/sr_sites_generated_custom_loc.txt")
GUI_OUT = Path("gui/journal_entry_widgets/sr_sites_generated_rows.gui")

HEADER = "# AUTO-GENERATED by scripts/generators/gen_solar_sites.py - do not edit manually.\n"


@dataclass(frozen=True)
class Site:
    key: str  # the sr_colony_<key> suffix
    name: str  # the world as its founding event's title names it (comments only)
    stage: int
    location: str  # the panel's grouping, LOCATIONS
    body: str | None  # launch-window body; None for Mercury and the Moon (never gated)
    event: int  # space_race_colony_events.<event>
    specs: tuple[str, str]  # suffixes of the event's two specializations, in option order
    discoveries: tuple[str, ...]  # seeded at founding, in the draw's order
    kind: str  # gfx/interface/icons/space_race_icons/colony_<kind>.dds
    room: int  # people, in thousands, before modules (slices 2-3 design § 10.2)
    slots: int  # generic module slots, shared by Habitat, Defences, Spaceport (slice 4 design § 1; no Spaceport on the Moon)
    ebase_room: int  # Extraplanetary Base levels the world's room holds
    ebase_grade: int  # the throughput a base level in its room gets, in percent

    @property
    def index(self) -> int:
        return SITES.index(self) + 1

    @property
    def propellant(self) -> bool:
        """Water or volatiles to crack: a Spaceport here refills a fleet fully
        (slice 6 design § 2)."""
        return self.key in PROPELLANT_WORLDS

    @property
    def ships(self) -> tuple[bool, bool]:
        """Which of its two specializations ship goods to Earth, and so run at
        nothing while it is blockaded (slice 6 design § 8)."""
        return SHIPPING[self.key]

    @property
    def resort_room(self) -> int:
        """Resort Colony levels the world's own room holds (#1948 design § 6.1)."""
        return RESORTS[self.key][0]

    @property
    def resort_draw(self) -> int:
        """The throughput a Resort Colony level in its room gets, in percent
        (#1948 design § 6.2)."""
        return RESORTS[self.key][1]


def _s(key, name, stage, location, body, event, specs, discoveries, kind, room, slots, ebase_room, ebase_grade):
    return Site(key, name, stage, location, body, event, tuple(specs), tuple(discoveries), kind, room,
                slots, ebase_room, ebase_grade)


