# module level, the priority weights (Closed, Low, Normal, High).
GROWTH_PER_MONTH = 0.002
# A held colony grows faster by its holder's GROWTH_MODIFIER, a script-only type
# (space_race_modifier_types.txt) that the Clade Citizenship law carries at +0.001,
# people born adapted to low gravity and radiation (era 13 spec § 7.3; its technology,
# Self-Directed Evolution, carried it until 2026-11-24). Each world's
# sr_site_growth_<key> reads it through the holder, as the Habitat share reads
# HABITAT_MODIFIER; a free colony has no holder and grows at the base rate.
GROWTH_MODIFIER = "country_sr_colony_growth_add"
# A world's base room for people, before Habitats and Terraforming (the owner,
# 2026-11-22): its table `room` times 1 plus its holder's ROOM_MODIFIER, a
# script-only type (space_race_modifier_types.txt) that Space Colonization and
# Terraforming carry at +0.5 each, so the base room doubles with both. A Habitat
# and Terraforming add shares of the base room, so they grow with it. Read through
# the holder as the Habitat share is, and the world keeps the best factor it has
# had (sr_site_room_mult_<key>, global, set in its monthly step and cleared on
# release), so a cession or a break-away doesn't cut its people (colony people
# design § 4.4's rule). A free colony has no holder and keeps its record.
ROOM_MODIFIER = "country_sr_colony_room_add"
# A crew of one module level (colony people design § 4.2; owner, 2026-11-22):
# 10,000 people, half with Artificial Intelligence, read through the world's
# holder (sr_site_crew_per_level_<key>), so a cession changes it with the holder.
# A free colony has no holder and counts at the full crew.
CREW_PER_LEVEL = 10000
AI_CREW_PER_LEVEL = 5000
AI_CREW_TECH = "artificial_intelligence"
PRIORITY_WEIGHTS = (0, 1, 2, 4)

# Modules (slice 4 design §§ 2-8). The two specializations share SPEC_BUDGET
# levels (the owner's D18). A Habitat adds HABITAT_BASE_SHARE of the base room a
# level plus the holder's HABITAT_MODIFIER, which the five slot technologies
# carry at +0.1 each (colony people design § 5), and the world keeps the best
# share it has had (sr_site_hab_share_<key>, global, set in its monthly step and
# cleared on release; § 4.4), so a cession to a holder with fewer of them, or a
# break-away, keeps the room its Habitats were built with. Types, in the order
# fabrication takes a colony's queue, with the code a shipment slot records.
SPEC_BUDGET = 4
HABITAT_BASE_SHARE = 0.5
HABITAT_MODIFIER = "country_sr_habitat_room_add"


# The facilities (colony management design § 7): generic modules that take a
# slot and need crews, each giving its effect per staffed level, summed over
# the colonies THIS holds that serve it (sr_mod_units_<key>). `ships`: stopped
# by a blockade as a goods-shipping specialization is. `modifier`: the entry
# modifier its units scale (sr_module_<key>), or None for a hook into another
# system's numbers (Extraplanetary Base room, fabrication and Space Command,
# command reliability, autonomy, a world's room for people). Codes 6 on, in
# this order: saves keep 1 to 5. Terraforming (16, era 13 spec § 7.11) is
# appended last, so the ten before it keep theirs, and only TERRAFORMABLE
# worlds take it (module_types() and its kin).
@dataclass(frozen=True)
class Facility:
    key: str
    name: str
    head: str  # the Modules view's column head
    ships: bool
    modifier: bool
    # A cost the entry declares at its staffed levels, though it is a hook and
    # has no benefit modifier: the Administration's authority (colony people
    # design § 7; the owner, 2026-11-22: "~25 per level").
    bills: bool = False


FACILITIES: tuple[Facility, ...] = (
    Facility("mine", "Mining Complex", "Mine", True, False),
    Facility("yard", "Orbital Yard", "Yard", True, False),
    Facility("lab", "Research Station", "Lab", False, True),
    Facility("culture", "Cultural Center", "Arts", False, True),
    # A hook since #1948: Resort Colony room at its world (+3% tourism output before).
    Facility("resort", "Off-World Resort", "Tour", True, False),
    Facility("black", "Black Site", "Spy", False, True),
    Facility("train", "Training Ground", "Camp", False, True),
    Facility("bunker", "Nuclear Command Center", "Nuke", False, False),
    Facility("foundry", "Materials Foundry", "Mat", True, True),
    Facility("admin", "Administration", "Gov", False, False, bills=True),
    Facility("terra", "Terraforming", "Terr", False, False),
)
FACILITY_TYPES = tuple(f.key for f in FACILITIES)
FACILITY = {f.key: f for f in FACILITIES}
# The modules that also take Space Forces Personnel under Full Colonies (the
# owner, 2026-11-25: "spaceport, defenses, black site, training ground, and
# nuclear command center should each use 1k ... Personnel (in addition to
# Crew)"): sr_pers_per_module (1,000) a level at a colony THIS holds and no one
# occupies, counted in service with the fleets and marines (sr_pers_module_levels,
# sr_pers_in_service), and their effects run at the holder's crewed share
# (sr_site_pers_share_<key>), as the fleets fire at it.
PERSONNEL_TYPES = ("def", "port", "black", "train", "bunker")
MODULE_TYPES = ("hab", "a", "b", "port", "def", *FACILITY_TYPES)
MODULE_CODES = {"a": 1, "b": 2, "hab": 3, "def": 4, "port": 5,
                **{t: 6 + n for n, t in enumerate(FACILITY_TYPES)}}
GENERIC_TYPES = ("hab", "def", "port", *FACILITY_TYPES)
CREWED_TYPES = ("a", "b", "def", "port", *FACILITY_TYPES)  # a Habitat houses the crews
SHIP_SLOTS = 8
QUEUE_SLOTS = 20  # the national module queue, first in first out (owner, 2026-10-25)
QUEUE_TOP_OP = QUEUE_SLOTS  # the move-up scripted GUI's op for place n's alt-click: n + this
MODULE_NAMES = {"a": "Specialization I", "b": "Specialization II", "hab": "Habitat",
                "def": "Defences", "port": "Spaceport", **{f.key: f.name for f in FACILITIES}}
MODULE_AI_VALUE = 8  # Cede Colony's AI value of a module level past the first

# No slots (colony people design § 4.1; owner, 2026-11-22): any module may be
# queued at any colony at the flat price, sr_module_points, and crews are the
# limit. The Habitat is the one capped module (§ 4.3): the table's `slots` (1 to
# 4) is its cap, sr_site_hab_cap_<key>, which no technology changes. Past it the
# n-th Habitat costs sr_module_points x (1 + n), with no top (the owner's call 7:
# today's limit of 8 past went), and one is queued only while the module stock
# can hold its price (sr_mod_fab_stock_cap, sr_colony_module_values.txt): the
# base stock of 500 holds the fourth's, and storage and a year's fabrication the
# rest, so Module Storage buys reach past the cap.

# The Modules view's lines of cells (colony management design § 8), in order;
# Terraforming on a fourth line of its own, shown on the worlds that take it.
MODULE_LINES = (("a", "b", "hab", "port", "def"), FACILITY_TYPES[:5], FACILITY_TYPES[5:10], ("terra",))

# Terraforming (era 13 spec § 7.11): works on the world itself, so its room for
# people grows over decades. Only the worlds with the gravity and the volatiles
# to keep an air made for them: Mars's five sites, Venus (cooled under a
# sunshade), Titan, and Jupiter's two largest moons, Ganymede (the one moon
# with a magnetic field of its own) and Callisto (outside Jupiter's radiation
# belts). Not the Moon or Mercury (no volatiles to make an air from), Io and
# Europa (the radiation belts), nor the small moons, asteroids and dwarf
# planets (too little gravity to hold one).
#
# A staffed level does a month's work a month into the world's record
# (sr_site_terra_done_<key>, global: the world's, so a cession, a release or a
# level coming down keeps it); TERRA_LEVEL_MONTHS of work add TERRA_ROOM_SHARE
# of the base room, so one level adds 4% of the base room a year and reaches
# +100% in 25 years. Up to TERRA_MAX_LEVELS at a world at once, counting queue
# and shipments; the whole job is that many shares (+300%), at least 25 years.
# Finished, the levels stand down and free their slots. Queued with the holder's
# TERRA_MARKER (the technology's), occupation stops the work.
TERRAFORMABLE = frozenset({"valles_marineris", "olympus_mons", "hellas_planitia", "utopia_planitia",
                           "arcadia_planitia", "venus", "titan", "ganymede", "callisto"})
TERRA_LEVEL_MONTHS = 300
TERRA_ROOM_SHARE = 1
TERRA_MAX_LEVELS = 3
TERRA_FULL_MONTHS = TERRA_MAX_LEVELS * TERRA_LEVEL_MONTHS
TERRA_MARKER = "country_sr_terraforming_bool"
TERRA_AI_FILL = 0.5  # the AI terraforms a world once its people fill half its room

# Extraplanetary Bases from colonies (design § 9): every country's near-Earth
# room, the technology it needs (the Extraplanetary Base itself comes earlier,
# with In-Situ Resource Utilization: lunar colonization design § 6), and the
# grade of a level past all of its room, in percent.
NEAR_EARTH_ROOM = 10
NEAR_EARTH_TECH = "asteroid_mining"
OVERFLOW_GRADE = -75

# The Resort Colony (#1948 design § 6.1): Earth orbit's room, for every country
# with the building's technology, at draw 0; the draw of a level past all of the
# room, the base's figure but its own constant.
ORBIT_RESORT_ROOM = 10
RESORT_TECH = "space_colonization"
RESORT_OVERFLOW_DRAW = -75


# The two buildings whose levels fill a room their country's colonies give it
# (#1951): the Extraplanetary Base (design § 9) and the Resort Colony (#1948
# design § 6). The resort's room began as a copy of the base's; what is still
# the same shape is written from here, one function a piece called once for each
# building: the levels built and queued, the room (each world's and the
# country's), the build gates, the next-day hook and the overview cell's display
# values. Where the levels go is each one's own: the base's month places them by
# record (gen_ebase.py, ground types design § 8), the resort's room fills best
# draw first (render_resort_fill). So are the two refreshes, the hook's events
# (space_race_events.110, .112), the cell's last line and the base's
# sr_disp_ebase_next_past / _next_profit, all hand-written.
@dataclass(frozen=True)
class RoomBuilding:
    key: str  # the names' infix: sr_<key>_room_total, sr_site_<key>_room_<site>, sr_disp_<key>_*
    name: str  # comments only
    design: str  # where its room is designed, comments only
    building: str
    tech: str  # the building's technology: the overview cell shows with it
    home: str  # the room every country has, comments only
    home_tech: str  # the technology that room needs
    home_room: int
    site_room: str  # the Site attribute holding a world's own room
    facility: str  # the module whose staffed levels add sr_mod_<facility>_room to its world's room
    measure: str  # what a level gets in the room, in percent: var:sr_<key>_<measure>, its average
    overflow: int  # a level past all of the room, in percent
    hook_event: str  # the room's refresh the day after a level finishes


EBASE = RoomBuilding("ebase", "Extraplanetary Base", "design § 9", "building_space_mine",
                     "in_situ_resource_utilization", "the near-Earth asteroids", NEAR_EARTH_TECH, NEAR_EARTH_ROOM,
                     "ebase_room", "mine", "grade", OVERFLOW_GRADE, "space_race_events.110")
RESORT = RoomBuilding("resort", "Resort Colony", "#1948 design § 6", "building_space_resort",
                      RESORT_TECH, "Earth orbit", RESORT_TECH, ORBIT_RESORT_ROOM,
                      "resort_room", "resort", "draw", RESORT_OVERFLOW_DRAW, "space_race_events.112")
ROOM_BUILDINGS = (EBASE, RESORT)

# The overview cell shows built and queued levels apart ("9999 +999 / 9999") only
# while each figure fits under these (test_space_race_labels.py measures the word
# at them); otherwise their sum.
SPLIT_QUEUED_UNDER = 1000
SPLIT_FIGURE_UNDER = 10000

# The Moon's six worlds (lunar colonization design § 3): stage 0, at Earth's
# location, never gated, founded the month their fleet leaves (§ 3.3). A module
# for one takes no shipment slot either (the owner, 2026-11-15): it is installed
# the month it is built, unless Earth is blockaded (sr_mod_fab_build_lunar).
LUNAR: tuple[Site, ...] = tuple(s for s in SITES if s.stage == 0)


# The worlds with several sites on them (owner, 2026-11-24): a holder's
# marines on one of its colonies there defend each of its colonies on that
# world, and its Defences fire for each of them and add half their hardness.
# The Moon's six sites are its Earth location's, Mars's five its location's;
# every other site is a world of its own (Jupiter's six are six moons). An
# Orbital Yard reaches further: YARD_SYSTEMS below.
SHARED_WORLDS: dict[str, str] = {"moon": "the Moon", "mars": "Mars"}


def world_of(site: Site) -> str:
    """The world the site stands on: "moon", "mars", or the site's own key."""
    if site in LUNAR:
        return "moon"
    if site.location == "mars":
        return "mars"
    return site.key


def world_mates(site: Site) -> list[Site]:
    """The other sites on the same world, in table order (none for most)."""
    return [s for s in SITES if s is not site and world_of(s) == world_of(site)]


# The places an Orbital Yard builds for (the owner, 2026-11-25: "all Jupiter's
# moons, Saturn's moons, etc. should count as the same place - i.e. you can
# build modules on Europa with an Orbital Yard on Io. This should not be the
# case for defenses, though."). A yard builds for every colony of its holder's
# on its world (world_of) and, around a giant planet, on any of that planet's
# moons. Only the yard reads this: Defences and marines still share by
# world_of, so each of those moons defends itself. The asteroids, the Kuiper
# Belt's dwarf planets, Venus and Mercury stay a place each.
YARD_SYSTEMS: dict[str, str] = {"jupiter": "Jupiter", "saturn": "Saturn", "uranus": "Uranus",
                                "neptune": "Neptune"}

# The places with several sites, each with its own hover on a yard's cell
# (je_space_race_widget_mod_yard_tt_<place>); every other site's names itself
# alone (yard_tooltip).
YARD_PLACES: tuple[str, ...] = (*SHARED_WORLDS, *YARD_SYSTEMS)


def yard_place_of(site: Site) -> str:
    """The place an Orbital Yard at `site` builds for: its planet's name around a
    giant planet ("jupiter", "saturn", "uranus", "neptune"), else world_of."""
    if site.location in YARD_SYSTEMS:
        return site.location
    return world_of(site)


def yard_mates(site: Site) -> list[Site]:
    """The other sites a yard at `site` builds for, and whose yards build for it,
    in table order: its world's (world_mates) and its planet's other moons."""
    return [s for s in SITES if s is not site and yard_place_of(s) == yard_place_of(site)]


def yard_tooltip(site: Site) -> str:
    """The loc key of the hover on the site's Orbital Yard cell, which names the
    colonies its yard builds for."""
    place = yard_place_of(site)
    return f"je_space_race_widget_mod_yard_tt_{place if place in YARD_PLACES else 'alone'}"


def lunar_open_test(var: str, place_type: str | None = None) -> str:
    """A country-scope trigger: `var` (a queue place's site) names a lunar world
    that can take a module now, neither blockaded nor occupied (a module built
    for one would be lost at once; review of #1847); false while it is unset.
    With `place_type` (the place's type variable), also one the stock can pay
    for: every module at sr_module_points, a Habitat at the world's
    sr_mod_hab_cost_<key> (sr_mq_head_cost's prices)."""
    parts = []
    for s in LUNAR:
        terms = [f"{var} ?= {s.index}", f"NOT = {{ has_global_variable = sr_site_blockaded_{s.key} }}",
                 f"NOT = {{ has_global_variable = sr_site_occupier_{s.key} }}", *_paid_terms(s, place_type)]
        parts.append("AND = { " + " ".join(terms) + " }")
    return "OR = { " + " ".join(parts) + " }"


def _paid_terms(site: Site, place_type: str | None) -> list[str]:
    """With `place_type` (a queue place's type variable), the stock can pay for
    the place's module at `site`: every module at sr_module_points, a Habitat at
    the world's sr_mod_hab_cost_<key> (sr_mq_head_cost's prices). None without."""
    if not place_type:
        return []
    return ["sr_mod_fab_stock_value >= sr_module_points",
            f"OR = {{ NOT = {{ {place_type} ?= {MODULE_CODES['hab']} }} sr_mod_fab_stock_value >= sr_mod_hab_cost_{site.key} }}"]


def ready_test(var: str, place_type: str | None = None) -> str:
    """A country-scope trigger: `var` (a queue place's site) names a world whose
    module can be built now (the owner, 2026-11-23: a module waiting for a launch
    window stays in the queue, its points in the stock, rather than holding a
    shipment slot, and the first module that can go is built first). A world
    with one of our Orbital Yards on it (yard_ready_test: no slot, no window, the
    owner, 2026-11-24), a lunar
    world that can take it now (lunar_open_test: it needs no slot), or, with a
    shipment slot free, Mercury, or a world whose window is open or opens within
    sr_mod_build_lead_months (sr_mod_wait_months_<key>: 0 while it is open or
    windows don't bind THIS, and a window's last month counts as missed). False
    while `var` is unset. Launches barred is the caller's test. With
    `place_type`, also one the stock can pay for (_paid_terms)."""
    slot = []
    for s in SITES:
        if s in LUNAR:
            continue
        terms = [f"{var} ?= {s.index}"]
        if s.body:
            terms.append(f"sr_mod_wait_months_{s.key} <= sr_mod_build_lead_months")
        slot.append("AND = { " + " ".join(terms + _paid_terms(s, place_type)) + " }")
    return ("OR = { " + yard_ready_test(var, place_type) + " " + lunar_open_test(var, place_type)
            + " AND = { sr_ms_has_free_slot = yes OR = { " + " ".join(slot) + " } } }")


def yard_builds_test(site: Site) -> str:
    """A country-scope trigger: a module for `site` is built at an Orbital Yard in
    its place (the owner, 2026-11-24, and 2026-11-25 for a giant planet's moons):
    THIS holds the site, neither blockaded nor occupied, and has an Orbital Yard
    level there or at a colony of its own in the same place that serves it
    (yard_mates: its world, or any moon of its planet; site_serves: held, not
    blockaded, not occupied, as the yard's fabrication points need). Such a
    module takes no shipment slot, waits for no launch window or launch, and is
    not one of the month's sr_mod_fab_per_month (sr_mod_month); it costs the
    same points."""
    yards = [f"{level_value('yard', site)} >= 1"]
    yards += [f"AND = {{ {site_serves(m)} {level_value('yard', m)} >= 1 }}"
              for m in yard_mates(site) if "yard" in generic_types(m)]
    return f"{site_serves(site)} OR = {{ {' '.join(yards)} }}"


def yard_ready_test(var: str, place_type: str | None = None) -> str:
    """A country-scope trigger: `var` (a queue place's site) names a world whose
    module is built at an Orbital Yard in its place now (sr_site_yard_builds_<key>,
    yard_builds_test); false while it is unset. With `place_type`, also one the
    stock can pay for (_paid_terms)."""
    parts = [" ".join([f"{var} ?= {s.index}", f"sr_site_yard_builds_{s.key} = yes", *_paid_terms(s, place_type)])
             for s in SITES if "yard" in generic_types(s)]
    return "OR = { " + " ".join(f"AND = {{ {p} }}" for p in parts) + " }"

# No Spaceport on a lunar world (design § 3.1): fleets dock at Earth, the same
# location. module_types() and its kin
# drop the Spaceport for these, so no queue, shipment, building or panel cell
# is emitted for one; sr_site_port_value_<key> stays, a constant 0, because the
# integrity step (sr_fleet_combat_effects.txt) reads it for every world.
NO_SPACEPORT = frozenset(s.key for s in SITES if s.location == "earth")

# The Moon Landing's "Where the Eagle Shall Land" choice (space_race_events.txt,
# the country variable sr_moon_site_<site>) gives -25% progress on the lunar
# world it names, for that country (design § 3.4): sr_landing_site_factor in
# sr_cf_goal_<key>, so the target's goal and the fleet's cost both show it.
# Peary and Imbrium match no landing site.
LANDING_SITES = {
    "shackleton": "sr_moon_site_shackleton",
    "tranquility": "sr_moon_site_tranquility",
    "marius_hills": "sr_moon_site_equatorial",
    "daedalus": "sr_moon_site_far_side",
}


def _types_at(site: Site, types: tuple[str, ...]) -> tuple[str, ...]:
    return tuple(t for t in types if not (t == "port" and site.key in NO_SPACEPORT)
                 and not (t == "terra" and site.key not in TERRAFORMABLE))


def terraformable(site: Site) -> bool:
    return site.key in TERRAFORMABLE


def module_types(site: Site) -> tuple[str, ...]:
    """MODULE_TYPES the world takes: all but a lunar world's Spaceport, and
    Terraforming only where it makes sense (TERRAFORMABLE)."""
    return _types_at(site, MODULE_TYPES)


def generic_types(site: Site) -> tuple[str, ...]:
    """GENERIC_TYPES the world takes (its slots)."""
    return _types_at(site, GENERIC_TYPES)


def crewed_types(site: Site) -> tuple[str, ...]:
    """CREWED_TYPES the world takes."""
    return _types_at(site, CREWED_TYPES)


def spec_modifiers(site: Site) -> tuple[str, str]:
    prefix = SPEC_PREFIX.get(site.key, site.key)
    a, b = (f"sr_colony_{prefix}_{suffix}" for suffix in site.specs)
    return a, b


def discovery_modifiers(discovery: str) -> tuple[str, str]:
    """A discovery's two outcomes, in option order: the events'
    sr_site_choose_<name>, the boon's tooltip (<name>_tt) under simple and full
    colonies (DISCOVERY_BOONS), and the modifier races only declares."""
    return f"sr_discovery_{discovery}_a", f"sr_discovery_{discovery}_b"


def site_boons(site: Site) -> dict[str, list[tuple[str, int]]]:
    """The module types the world's discoveries can boost, each with the
    (discovery, option) pairs that boost it, in the table's order."""
    out: dict[str, list[tuple[str, int]]] = {}
    for d in site.discoveries:
        for option, t in enumerate(DISCOVERY_BOONS[d], start=1):
            out.setdefault(t, []).append((d, option))
    return out


def boosted(site: Site, t: str) -> bool:
    return t in site_boons(site)


def eff_value(site: Site, t: str) -> str:
    """The any-scope value of a facility's effective levels at the world: its
    staffed levels, times its boon where a discovery there can boost it."""
    k = site.key
    return f"sr_site_{t}_eff_{k}" if boosted(site, t) else f"sr_site_{t}_staffed_{k}"


def hab_share_eff(site: Site) -> str:
    """The share of the base room a Habitat level adds at the world, its boon
    included where a discovery there can boost Habitats."""
    k = site.key
    return f"sr_site_hab_share_eff_{k}" if boosted(site, "hab") else f"sr_site_hab_share_value_{k}"


def module_vars(site: Site) -> list[str]:
    """The world's module levels (slice 4 design § 2)."""
    k = site.key
    return [f"sr_site_lvl_a_{k}", f"sr_site_lvl_b_{k}", *(f"sr_site_{t}_{k}" for t in generic_types(site))]


def level_value(t: str, site: Site) -> str:
    """The any-scope value of the world's level of module type t."""
    return f"sr_site_lvl_{t}_value_{site.key}" if t in ("a", "b") else f"sr_site_{t}_value_{site.key}"


def stage_sites(stage: int) -> list[Site]:
    return [s for s in SITES if s.stage == stage]


def site_building(site: Site) -> str:
    return f"building_sr_site_{site.key}"


# A world's name in the overview's 154-wide cells (audit SPC-6; 16-point
# tooltip face): sr_site_name_<key>, or for a name too long for them its short
# form, sr_site_short_<key> (test_space_race_labels.py measures every one).
SHORT_NAMES = frozenset({"venus", "shackleton"})


def overview_name_key(site: Site) -> str:
    return f"sr_site_short_{site.key}" if site.key in SHORT_NAMES else f"sr_site_name_{site.key}"


def panel_order() -> list[Site]:
    return [s for loc in LOCATIONS for s in SITES if s.location == loc]


def ebase_tiers() -> list[Site | None]:
    """The Extraplanetary Base room in filling order (design § 9): the best grade
    first, ties in table order, the near-Earth room (None) first among grade 0."""
    keyed = [((-s.ebase_grade, 1, s.index), s) for s in SITES] + [((0, 0, 0), None)]
    return [s for _, s in sorted(keyed, key=lambda pair: pair[0])]


def resort_tiers() -> list[Site | None]:
    """The Resort Colony room in filling order (#1948 design § 6.3): the best
    draw first, ties in table order, Earth orbit (None) first among draw 0."""
    keyed = [((-s.resort_draw, 1, s.index), s) for s in SITES] + [((0, 0, 0), None)]
    return [s for _, s in sorted(keyed, key=lambda pair: pair[0])]


def choices() -> list[tuple[str, Site, str, int]]:
    """Every modifier an option of the founding and discovery events grants
    (sr_site_choose_<modifier>): (modifier, site, kind, option)."""
    out = []
    for site in SITES:
        for option, modifier in enumerate(spec_modifiers(site), start=1):
            out.append((modifier, site, "spec", option))
        for discovery in site.discoveries:
            for option, modifier in enumerate(discovery_modifiers(discovery), start=1):
                out.append((modifier, site, discovery, option))
    return out


# ---------------------------------------------------------------------------
# The founding draw and the stage check
# ---------------------------------------------------------------------------

# Stages 3-5 need Deep Space Exploration or a colony beyond the Moon, under
# every setting (design § 4): a lunar colony alone keeps the entry's
# `possible` (its first branch), so the draw and the target test it per world.
DEEP_SPACE_OPEN = ("OR = { modifier:country_sr_deep_space_exploration_program_bool = yes "
                   "sr_has_colony_beyond_moon = yes }")


def _draw_branch(site: Site, stage0: bool = False) -> list[str]:
    """One world's branch of the draw. `stage0`: the stage-0 block's own lunar
    worlds, which carry the lunar_stage0_draw self-check's OK (Races Only's
    first stage founds; lunar colonization plan, review focus 4)."""
    t = "\t\t\t"
    lines = [f"{t}10 = {{", f"{t}\ttrigger = {{",
             f"{t}\t\tNOT = {{ has_global_variable = sr_colony_{site.key} }}"]
    if site.stage >= 1:
        # Beyond the Moon needs the Mars Landing (lunar colonization design § 4),
        # in whichever stage's block the world is listed.
        lines.append(f"{t}\t\tsr_colonization_beyond_moon = yes")
    if site.body is None:
        lines.append(f"{t}\t\tsr_launch_ungated_departs = yes")
    else:
        lines.append(f"{t}\t\tsr_launch_site_departs = {{ BODY = {site.body} }}")
    if site.stage >= 3:
        lines.append(f"{t}\t\t{DEEP_SPACE_OPEN}")
    lines += [f"{t}\t}}",
              f"{t}\tset_global_variable = {{ name = sr_colony_{site.key} value = yes }}",
              f"{t}\tset_global_variable = {{ name = sr_site_holder_{site.key} value = root }}",
              f"{t}\tsr_site_sync_{site.key} = yes"]
    if site in LUNAR:
        # The first lunar colony takes the Moon Base's place (design § 3.6), in
        # the stage-0 block and as a released world under a later stage alike.
        lines.append(f"{t}\tsr_lunar_colony_founded = yes")
    if site.body is not None:
        lines.append(f"{t}\tsr_launch_window_gate_check = {{ BODY = {site.body} }}")
    if stage0:
        lines += [f"{t}\tif = {{",
                  f"{t}\t\tlimit = {{ NOT = {{ has_global_variable = sr_lunar_stage0_draw_ok_logged }} }}",
                  f"{t}\t\tset_global_variable = {{ name = sr_lunar_stage0_draw_ok_logged value = yes }}",
                  f'{t}\t\tdebug_log = "TE_SELF_CHECK OK lunar_stage0_draw world={site.key} '
                  "country=[THIS.GetCountry.GetNameNoFormatting] (the Moon's stage drew and founded a world "
                  'under Races Only; docs/testing/solar-colonies-playtest.md) date=[TimeKeeper.GetCurrentDate.GetString]"',
                  f"{t}\t}}"]
    for discovery in site.discoveries:
        lines.append(f"{t}\tsr_seed_colony_discovery = {{ DISCOVERY = {discovery} }}")
    lines += [f"{t}\ttrigger_event = {{ id = space_race_colony_events.{site.event} }}", f"{t}}}"]
    return lines


def render_draw() -> list[str]:
    out = [
        "# Solar System Colonization - establish a colony at a random unclaimed location.",
        "# Only a site a fleet can leave for now is drawn, and only among the cheapest",
        "# (Global Commons § 5.2): each site's trigger asks sr_launch_site_departs for",
        "# its window body (Mercury and the Moon, never gated, sr_launch_ungated_departs). The body of",
        "# each site is the generator's BODIES table (scripts/generators/",
        "# gen_launch_windows.py; test_launch_windows.py holds the two equal). Called",
        "# from sr_launch_month only, which checks first that some site can depart.",
        "# The claim names its holder (sr_site_holder_<key>), and the site's sync puts",
        "# it on the holder's count; the specialization follows in the event. Each",
        "# stage also lists every earlier stage's worlds: they are claimed while those",
        "# stages are full, so their branches pass only for a released world (a dead",
        "# holder with no heir, design § 6).",
        "sr_establish_colony_effect = {",
        "\t# Initialize stage if needed",
        "\tif = {",
        "\t\tlimit = { NOT = { has_global_variable = sr_colonization_stage } }",
        "\t\tset_global_variable = { name = sr_colonization_stage value = 0 }",
        "\t}",
        "\t# Count the world's claimed sites before the draw. Once every site is",
        "\t# claimed (stage 5 full) the stage lists below have no valid entry and",
        "\t# claim nothing, so the first-colony charter must follow an actual claim,",
        "\t# not the bar filling.",
        "\tset_local_variable = { name = sr_colonies_claimed_before value = sr_total_global_colonies }",
        "",
    ]
    for stage in STAGES:
        out.append(f"\t# ===== STAGE {stage}: {STAGE_TITLES[stage]} =====")
        out.append("\tif = {" if stage == STAGES[0] else "\telse_if = {")
        out.append(f"\t\tlimit = {{ global_var:sr_colonization_stage = {stage} }}")
        out.append("\t\trandom_list = {")
        for site in stage_sites(stage):
            out += _draw_branch(site, stage0=stage == 0)
        if stage > STAGES[0]:
            out.append("\t\t\t# Released worlds of the stages before")
            for earlier in range(STAGES[0], stage):
                for site in stage_sites(earlier):
                    out += _draw_branch(site)
        out += ["\t\t}", "\t}"]
    out += _draw_trailer() + ["}"]
    return out


def render_stage_check() -> list[str]:
    out = ["# Check if current colonization stage is complete and advance",
           "sr_check_colony_stage_effect = {"]
    for stage in STAGES:
        nxt = "All done" if stage == 5 else f"Stage {stage + 1}"
        out.append(f"\t# Stage {stage} complete → {nxt}")
        out.append("\tif = {" if stage == STAGES[0] else "\telse_if = {")
        out += ["\t\tlimit = {", f"\t\t\tglobal_var:sr_colonization_stage = {stage}"]
        out += [f"\t\t\thas_global_variable = sr_colony_{s.key}" for s in stage_sites(stage)]
        out.append("\t\t}")
        if stage == 5:
            out.append("\t\tset_global_variable = { name = sr_all_colonies_complete value = yes }")
        else:
            out.append(f"\t\tset_global_variable = {{ name = sr_colonization_stage value = {stage + 1} }}")
        out.append("\t}")
    out.append("}")
    return out


# ---------------------------------------------------------------------------
# The record: sync, mirror, release, transfer, the monthly step
# ---------------------------------------------------------------------------

def _mirror_on(site: Site) -> list[str]:
    a, b = spec_modifiers(site)
    k = site.key
    # Each specialization at its level times the colony's staffing (slice 4
    # design § 3): the founding choice reads level 1, the other 0, until a
    # module raises them.
    # The entry declares each one at sr_site_mult_<a|b>_<key> while it is held
    # (render_entry_declarations).
    out = [f"sr_site_mirror_on_{k} = {{"]
    for slot, modifier in (("a", a), ("b", b)):
        out += ["\tif = {",
                f"\t\tlimit = {{ sr_site_lvl_{slot}_value_{k} >= 1 }}",
                f"\t\tsr_site_mark_held = {{ VAR = {modifier}_held }}",
                "\t}",
                "\telse = {",
                f"\t\tsr_site_clear_held = {{ VAR = {modifier}_held }}",
                "\t}"]
    # A discovery made there is ours as made. Its outcome is the world's boon
    # under simple and full colonies (DISCOVERY_BOONS, read from the record by
    # sr_site_boon_<type>_<key>), and under races only, which has no modules, the
    # outcome's modifier, which the entry declares while <modifier>_held is set.
    for d in site.discoveries:
        da, db = discovery_modifiers(d)
        out += ["\tif = {",
                f"\t\tlimit = {{ has_global_variable = sr_site_disc_{d} global_var:sr_site_disc_{d} = 1 }}",
                f"\t\tsr_site_mark_held = {{ VAR = {da}_held }}",
                f"\t\tsr_site_clear_held = {{ VAR = {db}_held }}",
                f"\t\tsr_site_set_discovery_done = {{ DISCOVERY = {d} }}",
                "\t}",
                "\telse_if = {",
                f"\t\tlimit = {{ has_global_variable = sr_site_disc_{d} global_var:sr_site_disc_{d} = 2 }}",
                f"\t\tsr_site_mark_held = {{ VAR = {db}_held }}",
                f"\t\tsr_site_clear_held = {{ VAR = {da}_held }}",
                f"\t\tsr_site_set_discovery_done = {{ DISCOVERY = {d} }}",
                "\t}",
                "\telse_if = {",
                f"\t\tlimit = {{ has_global_variable = sr_site_disc_{d}_pending }}",
                f"\t\tsr_site_set_discovery_pending = {{ DISCOVERY = {d} }}",
                "\t}"]
    out += ["\tset_variable = { name = sr_colony_count value = sr_sites_held_count }", "}"]
    return out


def _unmirror(site: Site) -> list[str]:
    a, b = spec_modifiers(site)
    out = [f"sr_site_unmirror_{site.key} = {{",
           f"\tsr_site_clear_held = {{ VAR = {a}_held }}",
           f"\tsr_site_clear_held = {{ VAR = {b}_held }}"]
    for d in site.discoveries:
        da, db = discovery_modifiers(d)
        out += [f"\tsr_site_clear_held = {{ VAR = {da}_held }}",
                f"\tsr_site_clear_held = {{ VAR = {db}_held }}",
                f"\tsr_site_clear_discovery = {{ DISCOVERY = {d} }}"]
    out += [f"\tif = {{ limit = {{ has_variable = sr_emig_prio_{site.key} }} remove_variable = sr_emig_prio_{site.key} }}"]
    # The world leaves the holder's module queue (slice 4 design § 7), and any
    # level it was taking down stays up (dismantling, owner 2026-10-31).
    out += [f"\tsr_mq_drop_site = {{ INDEX = {site.index} }}", f"\tsr_md_clear_{site.key} = yes"]
    out += ["\tset_variable = { name = sr_colony_count value = sr_sites_held_count }", "}"]
    return out


def _sync(site: Site) -> list[str]:
    k = site.key
    return [
        f"sr_site_sync_{k} = {{",
        "\t# The country that shows the site and no longer holds it loses it.",
        "\tif = {",
        "\t\tlimit = {",
        f"\t\t\thas_global_variable = sr_site_mirror_{k}",
        "\t\t\tOR = {",
        f"\t\t\t\tNOT = {{ has_global_variable = sr_site_holder_{k} }}",
        f"\t\t\t\tNOT = {{ global_var:sr_site_mirror_{k} ?= global_var:sr_site_holder_{k} }}",
        f"\t\t\t\thas_global_variable = sr_site_occupier_{k}",
        "\t\t\t}",
        "\t\t}",
        f"\t\tglobal_var:sr_site_mirror_{k} ?= {{",
        "\t\t\tif = {",
        "\t\t\t\tlimit = { is_country_alive = yes }",
        f"\t\t\t\tsr_site_unmirror_{k} = yes",
        "\t\t\t}",
        "\t\t}",
        f"\t\tremove_global_variable = sr_site_mirror_{k}",
        "\t}",
        "\t# The holder shows it, unless it is occupied (slice 6 design § 9.2: an occupied",
        "\t# world gives its modifiers to no one).",
        "\tif = {",
        "\t\tlimit = {",
        f"\t\t\tglobal_var:sr_site_holder_{k} ?= {{ is_country_alive = yes }}",
        f"\t\t\tNOT = {{ has_global_variable = sr_site_occupier_{k} }}",
        "\t\t}",
        f"\t\tglobal_var:sr_site_holder_{k} = {{ sr_site_mirror_on_{k} = yes }}",
        f"\t\tset_global_variable = {{ name = sr_site_mirror_{k} value = global_var:sr_site_holder_{k} }}",
        "\t}",
        "}",
    ]


def _release(site: Site) -> list[str]:
    k = site.key
    out = [f"sr_site_release_{k} = {{",
           f"\tif = {{ limit = {{ has_global_variable = sr_site_holder_{k} }} remove_global_variable = sr_site_holder_{k} }}",
           f"\tsr_site_sync_{k} = yes",
           f"\tif = {{ limit = {{ has_global_variable = sr_colony_{k} }} remove_global_variable = sr_colony_{k} }}",
           f"\tif = {{ limit = {{ has_global_variable = sr_site_spec_{k} }} remove_global_variable = sr_site_spec_{k} }}",
           f"\tif = {{ limit = {{ has_global_variable = sr_site_region_{k} }} remove_global_variable = sr_site_region_{k} }}",
           f"\tif = {{ limit = {{ has_global_variable = sr_site_pop_{k} }} remove_global_variable = sr_site_pop_{k} }}",
           f"\tif = {{ limit = {{ has_global_variable = sr_site_hab_share_{k} }} remove_global_variable = sr_site_hab_share_{k} }}",
           f"\tif = {{ limit = {{ has_global_variable = sr_site_room_mult_{k} }} remove_global_variable = sr_site_room_mult_{k} }}"]
    out += [f"\tif = {{ limit = {{ has_global_variable = {var} }} remove_global_variable = {var} }}"
            for var in module_vars(site)]
    for d in site.discoveries:
        out += [f"\tif = {{ limit = {{ has_global_variable = sr_site_disc_{d} }} remove_global_variable = sr_site_disc_{d} }}",
                f"\tif = {{ limit = {{ has_global_variable = sr_site_disc_{d}_pending }} remove_global_variable = sr_site_disc_{d}_pending }}"]
    # Slice 5: a released world is free of autonomy, freedom and ties too.
    out += [f"\tif = {{ limit = {{ has_global_variable = {var} }} remove_global_variable = {var} }}"
            for var in slice5_vars(site)]
    out += [f"\tsr_site_clear_ties_{k} = yes"]
    # Slice 6: its marines are lost, its integrity, occupation and blockade cleared
    # (a ruin is set after the release, by the destruction itself).
    out += [f"\tif = {{ limit = {{ has_global_variable = {var} }} remove_global_variable = {var} }}"
            for var in slice6_vars(site)]
    out += [f'\tdebug_log = "TE_SR_SITES released {k}"', "}"]
    return out


def _transfer(site: Site) -> list[str]:
    k = site.key
    return [
        f"# Moves {site.name} to scope:sr_site_to_{k}; scope:sr_site_from_{k}, when saved,",
        "# is the country it leaves. CAUSE names what follows (sr_site_effects.txt):",
        "# treaty (Cede Colony), heir (a dead holder's), quiet (an adoption).",
        f"sr_site_transfer_{k} = {{",
        "\tif = {",
        f"\t\tlimit = {{ scope:sr_site_to_{k} ?= {{ is_country_alive = yes }} }}",
        f"\t\tset_global_variable = {{ name = sr_site_holder_{k} value = scope:sr_site_to_{k} }}",
        "\t\t# The garrison is its holder's and goes home (slice 5 design § 1), and with it",
        "\t\t# the hold at the break level (sr_site_hold_<key>).",
        f"\t\tif = {{ limit = {{ has_global_variable = sr_site_garrison_{k} }} remove_global_variable = sr_site_garrison_{k} }}",
        f"\t\tif = {{ limit = {{ has_global_variable = sr_site_resisting_{k} }} remove_global_variable = sr_site_resisting_{k} }}",
        f"\t\tif = {{ limit = {{ has_global_variable = sr_site_garrison_due_{k} }} remove_global_variable = sr_site_garrison_due_{k} }}",
        "\t\t# A treaty ends an occupation (slice 6 design § 9.2); an heir takes the world",
        "\t\t# occupied. Marines stay with an ally of their owner, else go home (§ 9.6).",
        f"\t\tsr_site_transfer_marines = {{ KEY = {k} }}",
        f"\t\tsr_site_transfer_occupation_$CAUSE$ = {{ KEY = {k} }}",
        f"\t\tsr_site_sync_{k} = yes",
        f"\t\tscope:sr_site_to_{k} = {{ sr_site_gained_$CAUSE$ = {{ INDEX = {site.index} }} }}",
        f"\t\tscope:sr_site_from_{k} ?= {{",
        "\t\t\tif = {",
        "\t\t\t\tlimit = { is_country_alive = yes }",
        f"\t\t\t\tsr_site_lost_$CAUSE$ = {{ INDEX = {site.index} }}",
        "\t\t\t}",
        "\t\t}",
        "\t\tsr_sites_refresh_players = yes",
        "\t}",
        "}",
    ]


def _terra_monthly(site: Site) -> list[str]:
    """Terraforming's month (era 13 spec § 7.11), before the projection, so the
    sync sees levels that stand down."""
    if not terraformable(site):
        return []
    k = site.key
    return [
        "\t# 3b. Terraforming (simple and full; era 13 spec § 7.11): the world's works",
        "\t# advance by its staffed levels, up to the whole job, unless it is occupied",
        "\t# (sr_site_terra_step_<key>).",
        "\tif = {",
        "\t\tlimit = {",
        "\t\t\tsr_colonies_contested_enabled = yes",
        f"\t\t\tsr_site_terra_value_{k} > 0",
        "\t\t}",
        f"\t\tsr_site_terra_step_{k} = {{ MONTHS = 1 }}",
        "\t}",
    ]


def _terra_step(site: Site) -> list[str]:
    """MONTHS months of the world's terraforming at this month's pace; once it
    is finished, its levels stand down (era 13 spec § 7.11)."""
    k = site.key
    return [
        f"# {site.name}'s works, MONTHS months at this month's pace (its staffed",
        "# Terraforming levels; none while occupied), up to sr_terra_full_months. Finished,",
        "# the levels stand down and free their slots; the work done stays the world's.",
        f"sr_site_terra_step_{k} = {{",
        "\tif = {",
        f"\t\tlimit = {{ sr_site_terra_rate_{k} > 0 }}",
        "\t\tset_global_variable = {",
        f"\t\t\tname = sr_site_terra_done_{k}",
        "\t\t\tvalue = {",
        f"\t\t\t\tvalue = sr_site_terra_rate_{k}",
        "\t\t\t\tmultiply = $MONTHS$",
        f"\t\t\t\tadd = sr_site_terra_done_value_{k}",
        "\t\t\t\tmax = sr_terra_full_months",
        "\t\t\t}",
        "\t\t}",
        "\t}",
        "\tif = {",
        "\t\tlimit = {",
        f"\t\t\thas_global_variable = sr_site_terra_{k}",
        f"\t\t\tNOT = {{ sr_site_terra_open_{k} = yes }}",
        "\t\t}",
        f"\t\tremove_global_variable = sr_site_terra_{k}",
        f'\t\tdebug_log = "TE_SR_MODULES {k}: terraformed; its Terraforming levels stand down"',
        "\t}",
        "}",
    ]


def _monthly(site: Site) -> list[str]:
    k = site.key
    a, b = spec_modifiers(site)
    return [
        f"sr_site_monthly_{k} = {{",
        "\t# 1. The holder's capital, for the dead-holder rule.",
        f"\tglobal_var:sr_site_holder_{k} ?= {{",
        "\t\tif = {",
        "\t\t\tlimit = { is_country_alive = yes exists = capital }",
        f"\t\t\tset_global_variable = {{ name = sr_site_region_{k} value = capital.state_region }}",
        "\t\t\t# The best Habitat share the world has had (colony people design § 4.4).",
        f"\t\t\tset_global_variable = {{ name = sr_site_hab_share_{k} value = sr_site_hab_share_value_{k} }}",
        "\t\t\t# ... and the best base room factor (Space Colonization, Terraforming).",
        f"\t\t\tset_global_variable = {{ name = sr_site_room_mult_{k} value = sr_site_room_mult_value_{k} }}",
        "\t\t}",
        "\t}",
        "\t# 2. A dead holder: its capital region's owner inherits, or the world is released.",
        "\tif = {",
        "\t\tlimit = {",
        f"\t\t\thas_global_variable = sr_site_holder_{k}",
        f"\t\t\tNOT = {{ global_var:sr_site_holder_{k} ?= {{ is_country_alive = yes }} }}",
        "\t\t}",
        "\t\t# Self-check (once a game): which guard caught the dead holder.",
        "\t\tif = {",
        "\t\t\tlimit = { NOT = { has_global_variable = sr_sites_dead_holder_noted } }",
        "\t\t\tset_global_variable = { name = sr_sites_dead_holder_noted value = yes }",
        "\t\t\tif = {",
        f"\t\t\t\tlimit = {{ exists = global_var:sr_site_holder_{k} }}",
        f'\t\t\t\tdebug_log = "TE_SELF_CHECK OK site_dead_holder {k}: the stored country exists, is_country_alive = no caught it"',
        "\t\t\t}",
        "\t\t\telse = {",
        f'\t\t\t\tdebug_log = "TE_SELF_CHECK OK site_dead_holder {k}: exists caught it"',
        "\t\t\t}",
        "\t\t}",
        f"\t\tglobal_var:sr_site_region_{k} ?= {{",
        "\t\t\tordered_scope_state = {",
        "\t\t\t\tlimit = { owner = { sr_site_can_hold = yes } }",
        "\t\t\t\torder_by = state_population",
        "\t\t\t\tmax = 1",
        f"\t\t\t\towner = {{ save_scope_as = sr_site_to_{k} }}",
        "\t\t\t}",
        "\t\t}",
        "\t\tif = {",
        f"\t\t\tlimit = {{ exists = scope:sr_site_to_{k} }}",
        f"\t\t\tsr_site_transfer_{k} = {{ CAUSE = heir }}",
        "\t\t\tif = {",
        f"\t\t\t\tlimit = {{ NOT = {{ global_var:sr_site_holder_{k} ?= {{ is_country_alive = yes }} }} }}",
        f'\t\t\t\tdebug_log = "TE_SELF_CHECK BROKEN site_dead_holder {k}: the heir did not take it"',
        "\t\t\t}",
        "\t\t}",
        "\t\t# No heir: an occupied world passes to its occupier (slice 6 design § 9.2); a",
        "\t\t# world with people becomes a free colony under simple and full (slice 5",
        "\t\t# design § 5), any other is released.",
        "\t\telse_if = {",
        f"\t\t\tlimit = {{ global_var:sr_site_occupier_{k} ?= {{ sr_site_can_hold = yes }} }}",
        f"\t\t\tglobal_var:sr_site_occupier_{k} = {{ save_scope_as = sr_site_to_{k} }}",
        f"\t\t\tsr_site_transfer_{k} = {{ CAUSE = heir }}",
        "\t\t}",
        "\t\telse = {",
        f"\t\t\tsr_site_free_or_release_{k} = yes",
        "\t\t}",
        "\t}",
        "\t# 3. A claim with no holder (a free colony aside): a country showing it adopts it;",
        "\t# after the grace, released.",
        "\telse_if = {",
        "\t\tlimit = {",
        f"\t\t\thas_global_variable = sr_colony_{k}",
        f"\t\t\tNOT = {{ has_global_variable = sr_site_holder_{k} }}",
        f"\t\t\tNOT = {{ has_global_variable = sr_site_free_{k} }}",
        "\t\t}",
        "\t\trandom_country = {",
        "\t\t\tlimit = {",
        "\t\t\t\tis_country_alive = yes",
        f"\t\t\t\tOR = {{ has_variable = {a}_held has_variable = {b}_held }}",
        "\t\t\t}",
        f"\t\t\tsave_scope_as = sr_site_to_{k}",
        "\t\t}",
        "\t\tif = {",
        f"\t\t\tlimit = {{ exists = scope:sr_site_to_{k} }}",
        f"\t\t\tsr_site_transfer_{k} = {{ CAUSE = quiet }}",
        "\t\t}",
        "\t\telse = {",
        f"\t\t\tsr_site_release_{k} = yes",
        "\t\t}",
        "\t}",
        *_terra_monthly(site),
        "\t# 4. The projection.",
        f"\tsr_site_sync_{k} = yes",
        "\t# 5. A free colony: its suppliers, their ties, a petition (slice 5 design § 3).",
        "\tif = {",
        f"\t\tlimit = {{ has_global_variable = sr_site_free_{k} }}",
        f"\t\tsr_site_free_step_{k} = yes",
        "\t}",
        "\t# 6. Growth, up to the room (simple and full; slices 2-3 design § 10.2), less a",
        "\t# Habitat's share while one comes down (sr_site_room_held_<key>); at a free",
        "\t# colony only while someone supplies it. The month's factor, sr_site_growth_<key>,",
        "\t# is faster under the holder's Clade Citizenship law (era 13 spec § 7.3).",
        "\tif = {",
        "\t\tlimit = {",
        "\t\t\tsr_colonies_contested_enabled = yes",
        f"\t\t\thas_global_variable = sr_site_pop_{k}",
        f"\t\t\tglobal_var:sr_site_pop_{k} > 0",
        "\t\t\tOR = {",
        f"\t\t\t\tNOT = {{ has_global_variable = sr_site_free_{k} }}",
        f"\t\t\t\tsr_site_suppliers_value_{k} >= 1",
        "\t\t\t}",
        "\t\t}",
        "\t\tset_global_variable = {",
        f"\t\t\tname = sr_site_pop_{k}",
        "\t\t\tvalue = {",
        f"\t\t\t\tvalue = global_var:sr_site_pop_{k}",
        f"\t\t\t\tmultiply = sr_site_growth_{k}",
        f"\t\t\t\tmax = sr_site_room_held_{k}",
        "\t\t\t}",
        "\t\t}",
        "\t}",
        "\t# 7. A held colony's autonomy (simple and full; slice 5 design § 2).",
        "\tif = {",
        "\t\tlimit = {",
        "\t\t\tsr_colonies_contested_enabled = yes",
        f"\t\t\tglobal_var:sr_site_holder_{k} ?= {{ is_country_alive = yes }}",
        "\t\t}",
        f"\t\tglobal_var:sr_site_holder_{k} = {{ sr_site_aut_step_{k} = yes }}",
        "\t}",
        "\t# 8. Full colonies (slice 6 design §§ 7.3, 9): a garrison waiting for its marines,",
        "\t# integrity regained, an occupation returned at the peace.",
        "\tif = {",
        "\t\tlimit = { sr_colonies_full_enabled = yes }",
        "\t\tif = {",
        f"\t\t\tlimit = {{ has_global_variable = sr_site_garrison_due_{k} }}",
        f"\t\t\tsr_site_garrison_due_step = {{ KEY = {k} INDEX = {site.index} }}",
        "\t\t}",
        f"\t\tsr_site_integrity_step = {{ KEY = {k} }}",
        "\t\tif = {",
        f"\t\t\tlimit = {{ has_global_variable = sr_site_occupier_{k} }}",
        f"\t\t\tsr_site_occupation_step = {{ KEY = {k} INDEX = {site.index} }}",
        "\t\t}",
        "\t}",
        "}",
    ]


def render_dispatcher() -> list[str]:
    out = ["# ===== The choice dispatcher =====",
           "# sr_site_choose_<m>, an option of space_race_colony_events.1-40 or of",
           "# space_race_discovery_events. A specialization records the world's choice and",
           "# the world's sync marks <m>_held, which the entry's declaration reads",
           "# (common/journal_entries/sr_sites_generated.txt); the option shows the modifier",
           "# the entry declares from then on (a new colony's founding specialization is",
           "# level 1, multiplier 1). A discovery outcome records the discovery's choice,",
           "# which under simple and full colonies is the world's boon",
           "# (gen_solar_sites.DISCOVERY_BOONS: the module it makes stronger there, read by",
           "# sr_site_boon_<type>_<key>), the option's tooltip saying which, and under races",
           "# only, with no modules, the outcome's modifier, declared as a specialization's",
           "# is. ROOT = THIS is the country choosing. A world claimed under a save from",
           "# before the record existed gets its holder here."]
    show_modifier = "show_as_tooltip = {{ je:je_space_race_solar_colonization ?= {{ add_modifier = {{ name = {} }} }} }}"
    for modifier, site, kind, option in choices():
        k = site.key
        out.append(f"sr_site_choose_{modifier} = {{")
        if kind == "spec":
            out.append(f"\t{show_modifier.format(modifier)}")
        else:
            out += [f"\tif = {{ limit = {{ sr_colonies_contested_enabled = yes }} custom_tooltip = {modifier}_tt }}",
                    f"\telse = {{ {show_modifier.format(modifier)} }}"]
        out += ["\thidden_effect = {",
                f"\t\tset_variable = {{ name = {modifier}_held value = yes }}",
                f"\t\tif = {{ limit = {{ NOT = {{ has_global_variable = sr_site_holder_{k} }} }} "
                f"set_global_variable = {{ name = sr_site_holder_{k} value = root }} }}"]
        if kind == "spec":
            out.append(f"\t\tset_global_variable = {{ name = sr_site_spec_{k} value = {option} }}")
        else:
            out.append(f"\t\tset_global_variable = {{ name = sr_site_disc_{kind} value = {option} }}")
            out.append(f"\t\tif = {{ limit = {{ has_global_variable = sr_site_disc_{kind}_pending }} "
                       f"remove_global_variable = sr_site_disc_{kind}_pending }}")
        out += [f"\t\tsr_site_sync_{k} = yes", "\t}", "}"]
    return out


def render_monthly_list() -> list[str]:
    out = ["# ===== The global monthly step (sr_sites_global_monthly) =====",
           "sr_sites_monthly = {"]
    out += [f"\tsr_site_monthly_{s.key} = yes" for s in SITES]
    out.append("}")
