                f"\t\t\tglobal_var:sr_site_holder_{k} ?= scope:sr_cede_source",
                "\t\t}",
                f"\t\tscope:sr_cede_target = {{ save_scope_as = sr_site_to_{k} }}",
                f"\t\tscope:sr_cede_source = {{ save_scope_as = sr_site_from_{k} }}",
