def render_debug() -> list[str]:
    out = ["# ===== Console helpers (te_debug_space_race.2) =====",
           "# Log every world's record.",
           "sr_sites_debug_log = {"]
    for site in SITES:
        k = site.key
        out += ["\tif = {",
                f"\t\tlimit = {{ global_var:sr_site_holder_{k} ?= {{ is_country_alive = yes }} }}",
                f'\t\tglobal_var:sr_site_holder_{k} = {{ debug_log = "TE_SR_SITES {k}: held by [THIS.GetCountry.GetNameNoFormatting]" }}',
                "\t}",
                f"\telse_if = {{ limit = {{ has_global_variable = sr_site_holder_{k} }} "
                f'debug_log = "TE_SR_SITES {k}: held by a dead country" }}',
                f"\telse_if = {{ limit = {{ has_global_variable = sr_colony_{k} }} "
                f'debug_log = "TE_SR_SITES {k}: claimed, no holder" }}',
                f'\telse = {{ debug_log = "TE_SR_SITES {k}: unclaimed" }}']
